-- Paket ABT "abt-x5-kodepos-amplop-21okt" (21 Okt 2026): kode pos di ujung alamat penerima pada amplop relaas.
-- Variabel baru 9290-9293 (kode pos dari kode wilayah pihak; alamat + kode pos) dan 8172 diubah; 6 blangko amplop Derry disunting satu penanda (berkas_rtf.py).
-- 4 variabel baru, 1 baris diubah.
-- PRASYARAT (baca saja) "A|B|C|D|E|F": A = nomor baru (4) yang berisi LAIN dari paket (harus 0) | B = nomor baru yang sudah persis paket (0 pertama, 4 ulang) | C = baris yang akan diubah (1) yang masih berisi isi LAMA (1 pertama, 0 ulang) | D = yang sudah isi BARU (0 pertama, 1 ulang) | E = variabel lama yang dirujuk dan harus ada (0) | F = baris diubah yang isinya bukan lama bukan baru (harus 0).
-- Benar: "0|0|1|0|0|0" (pertama) atau "0|4|0|1|0|0" (pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (9290,9291,9292,9293) AND NOT ((no_var=9290 AND MD5(nama)='e6a090ac9cc353e4d8655d8a20c1c2be' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='470dd6add4d2054c150f4d79f9a28de8' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9291 AND MD5(nama)='dc88156127161e1e5e1c1f3d5dabbc8a' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='d3b043fa44636f52de26b0896b475c74' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9292 AND MD5(nama)='26059ed1ccf7f124f445925278090eb4' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f0e51968dd27a186dd9b5373a4ccb208' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9293 AND MD5(nama)='77298f3b85bd63c58a274022db1611af' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f484a6d9952ca1fae290c7fef266e0bd' AND IFNULL(MD5(default_data),'-')='-'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=9290 AND MD5(nama)='e6a090ac9cc353e4d8655d8a20c1c2be' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='470dd6add4d2054c150f4d79f9a28de8' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9291 AND MD5(nama)='dc88156127161e1e5e1c1f3d5dabbc8a' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='d3b043fa44636f52de26b0896b475c74' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9292 AND MD5(nama)='26059ed1ccf7f124f445925278090eb4' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f0e51968dd27a186dd9b5373a4ccb208' AND IFNULL(MD5(default_data),'-')='-') OR (no_var=9293 AND MD5(nama)='77298f3b85bd63c58a274022db1611af' AND data_type='data_sql' AND IFNULL(data_tabel,'')='' AND IFNULL(data_kolom,'')='' AND IFNULL(urutan_data,0)=0 AND referensi IS NULL AND multi_sidang IS NULL AND locked=0 AND IFNULL(MD5(sql_query),'-')='f484a6d9952ca1fae290c7fef266e0bd' AND IFNULL(MD5(default_data),'-')='-'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='bf7b5de148ddf1b8640de12667fe339a'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='f5a7bc688de1254b8f45445c5086d817'))), '|', (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (-1)), '|', (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (8172) AND NOT (((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='bf7b5de148ddf1b8640de12667fe339a')) OR ((no_var=8172 AND MD5(nama)='e0becf55b9e3c385cfc47911dd9bbce9' AND data_type='data_sql' AND MD5(sql_query)='f5a7bc688de1254b8f45445c5086d817'))))) AS prasyarat;
